window.kbPageData["views/entry/k-897e8abb53f8681a"] = {"key":"entry/k-897e8abb53f8681a","state":{"route":"entry/k-897e8abb53f8681a"},"node":{"id":"k-897e8abb53f8681a","mode":"k","title":"恒定工效下的工作量","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["恒定工效下工作量等于工效乘以实际工作时间"],"qs":["江苏 2023 A类 行测#61"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"工作效率恒定时，完成的工作量等于工作效率乘以实际工作时间。多队合作完成同一项工程时，各队完成的工作量相加得到工程总量。","review":{"definition":"工作效率恒定时，完成的工作量等于工作效率乘以实际工作时间。多队合作完成同一项工程时，各队完成的工作量相加得到工程总量。","explanation":"本题按各队各自的工作与休息周期计算出勤。甲先开工时，甲经过23天、实际出勤18天，乙经过21天、实际出勤15天。乙先开工时，甲经过15天、实际出勤12天，乙经过27天、实际出勤20天。两种安排完成的是同一项工程，因此有18×甲的日工效＋15×乙的日工效＝12×甲的日工效＋20×乙的日工效，得到甲、乙日工效之比为5∶6。代回得甲单独完成需要实际工作36天，最后一个工作日一结束就完工，期间有11个休息日，合计47天，选C。","references":[],"evidence":"18甲+15乙=12甲+20乙","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#61":{"paper":"江苏 2023 A类 行测","n":61,"mod":"数量关系","src":["22304fe4c340e19d7902.pdf",11],"asrc":["be17f9afe070cf13a0fb.pdf",18],"card":"6408dd8d57052de0c314f833","links":[{"id":"k-897e8abb53f8681a","role":"解题依据","why":"各队完成的工作量按实际出勤时间计算，两队的工作量之和等于工程总量。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-897e8abb53f8681a":[["江苏 2023 A类 行测#61"]]}};
